type PlatformContextValue = [PlatformState, (next: PlatformState | ((previous: PlatformState) => PlatformState)) => void];
const PlatformContext = createContext<PlatformContextValue | null>(null);

function PlatformProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<PlatformState>(() => loadPlatformState());
  const update = (next: PlatformState | ((previous: PlatformState) => PlatformState)) => setState((previous) => typeof next === 'function' ? next(previous) : next);
  useEffect(() => { savePlatformState(state); }, [state]);
  return <PlatformContext.Provider value={[state, update]}>{children}</PlatformContext.Provider>;
}

