function Button({ children, variant = 'primary', onClick, className = '', type = 'button', disabled = false, testId }: { children: ReactNode; variant?: 'primary' | 'outline' | 'ghost' | 'cream' | 'danger'; onClick?: () => void; className?: string; type?: 'button' | 'submit'; disabled?: boolean; testId?: string }) {
  const styles = {
    primary: 'bg-[#20283a] text-[#faf7ef] hover:bg-[#303a51] shadow-[0_3px_0_hsl(222_32%_12%/.14)]',
    outline: 'border border-[#d4d1c8] bg-[#fbfaf5] text-[#30394b] hover:border-[#9fa5ab] hover:bg-[#f4f0e5]',
    ghost: 'text-[#596170] hover:bg-[#eeece5] hover:text-[#20283a]',
    cream: 'bg-[#e5b95d] text-[#20283a] hover:bg-[#edc975] shadow-[0_3px_0_hsl(41_62%_35%/.16)]',
    danger: 'bg-[#f8e2de] text-[#9c3f36] hover:bg-[#f2d1cc]',
  };
  return <button type={type} onClick={onClick} disabled={disabled} className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-4 text-sm font-bold transition-all duration-200 disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`} data-testid={testId}>{children}</button>;
}

function StatusPill({ status }: { status: string }) {
  const positive = ['Published', 'Approved', 'Active', 'Ready', 'Valid'].includes(status);
  const warning = ['In review', 'Needs review', 'Draft'].includes(status);
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-bold ${positive ? 'bg-[#e3f0e8] text-[#236447]' : warning ? 'bg-[#fff0d1] text-[#835b14]' : 'bg-[#ebe8e1] text-[#68675f]'}`} data-testid={`status-${status.toLowerCase().replaceAll(' ', '-')}`}>{positive ? <CheckCircle2 size={12} /> : <Clock3 size={12} />}{status}</span>;
}

